/**
 * OpenAI Apps SDK type definitions for Sierra Web SDK integration
 * https://developers.openai.com/apps-sdk/build/custom-ux
 */

export type UnknownObject = {
    [key: string]: unknown;
};

export type OpenAiGlobals<
    ToolInput extends UnknownObject = UnknownObject,
    ToolOutput extends UnknownObject = UnknownObject,
    ToolResponseMetadata extends UnknownObject = UnknownObject,
    WidgetState extends UnknownObject = UnknownObject,
> = {
    theme: Theme;
    userAgent: UserAgent;
    locale: string;

    // layout
    maxHeight: number;
    displayMode: DisplayMode;
    safeArea: SafeArea;

    // state
    toolInput: ToolInput;
    toolOutput: ToolOutput | null;
    toolResponseMetadata: ToolResponseMetadata | null;
    widgetState: WidgetState | null;
};

export type API<WidgetState extends UnknownObject> = {
    /** Calls a tool on your MCP. Returns the full response. */
    callTool: (name: string, args: { [key: string]: unknown }) => Promise<unknown>;

    /** Triggers a followup turn in the ChatGPT conversation */
    sendFollowUpMessage: (args: { prompt: string }) => Promise<void>;

    /** Opens an external link, redirects web page or mobile app */
    openExternal(payload: { href: string }): void;

    /** For transitioning an app from inline to fullscreen or pip */
    requestDisplayMode: (args: { mode: DisplayMode }) => Promise<{
        /**
         * The granted display mode. The host may reject the request.
         * For mobile, PiP is always coerced to fullscreen.
         */
        mode: DisplayMode;
    }>;

    setWidgetState: (state: WidgetState) => Promise<void>;
};

// Dispatched when any global changes in the host page
// Note: SET_GLOBALS_EVENT_TYPE and SetGlobalsEvent runtime values are exported from @sierra/web-react
// to maintain @sierra/web as a type-only package

// Type declaration for the event type constant
export type SET_GLOBALS_EVENT_TYPE = "openai:set_globals";

// Type declaration for the event class
export interface SetGlobalsEvent
    extends CustomEvent<{
        globals: Partial<OpenAiGlobals>;
    }> {
    readonly type: SET_GLOBALS_EVENT_TYPE;
}

export type CallTool = (name: string, args: { [key: string]: unknown }) => Promise<unknown>;

export type DisplayMode = "pip" | "inline" | "fullscreen";

export type Theme = "light" | "dark";

export type SafeAreaInsets = {
    top: number;
    bottom: number;
    left: number;
    right: number;
};

export type SafeArea = {
    insets: SafeAreaInsets;
};

export type DeviceType = "mobile" | "tablet" | "desktop" | "unknown";

export type UserAgent = {
    device: { type: DeviceType };
    capabilities: {
        hover: boolean;
        touch: boolean;
    };
};

// Type for OpenAI tool output with custom attachments
export type OpenAIToolOutput = {
    custom_attachments?: {
        type: string;
        data: string;
    }[];
};

// Global declarations for OpenAI window properties
declare global {
    interface Window {
        openai?: API<UnknownObject> & OpenAiGlobals;
    }

    interface WindowEventMap {
        "openai:set_globals": SetGlobalsEvent;
    }
}
